import requests
import json

url = "https://chatapi.onechats.ai/v1/chat/completions"

payload = json.dumps({
  "model": "claude-sonnet-4-5-20250929",
  "temperature": 1,
  "n": 1,
  "stream": True,
  "stream_options": {
    "include_usage": True
  },
  "messages": [
    {
      "role": "system",
      "content": "1"
    },
    {
      "role": "user",
      "content": "2"
    }
  ]
})
headers = {
  'Content-Type': 'application/json',
  'Authorization': 'Bearer sk-.......'
}

response = requests.request("POST", url, headers=headers, data=payload)

print(response.text)
